import re

import wordfreq


def _normalised(text):
    counts = {}
    for word in text.split():
        word = re.sub(r"^\W+|\W+$", "", word).lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts


def pytest_configure(config):
    wordfreq.word_counts = _normalised

